function DiscoveryPollCard({ compact = false }: { compact?: boolean }) {
  const [selected,setSelected] = useState<string | null>(null);
  const total = discoveryOptions.reduce((sum,o)=>sum+o.votes,0) + (selected ? 1 : 0);
  return <section className={`rounded-[1.6rem] border border-[#7a2e17]/45 bg-[radial-gradient(circle_at_100%_0%,rgba(255,106,0,.08),transparent_35%),#0d0d0e] ${compact?"p-4":"p-5"}`}><div className="flex items-start justify-between gap-4"><div><MarkLabel kind="explore">Discovery</MarkLabel><h3 className={`${compact?"mt-2 text-xl":"mt-3 text-2xl"} font-serif font-bold`}>What should Kingston get next?</h3></div><Vote className="h-5 w-5 text-[#ff6a00]"/></div><p className="mt-2 text-xs text-white/45">Your signal helps show where demand is forming.</p><div className="mt-4 space-y-2">{discoveryOptions.map(option=>{const votes=option.votes+(selected===option.id?1:0);const pct=Math.round((votes/total)*100);return <button key={option.id} type="button" onClick={()=>setSelected(option.id)} className={`relative w-full overflow-hidden rounded-xl border px-4 py-3 text-left ${selected===option.id?"border-[#f6c453]/60":"border-white/10"}`}><span className="absolute inset-y-0 left-0 bg-[#ff6a00]/10" style={{width:selected?`${pct}%`:"0%"}}/><span className="relative flex items-center justify-between gap-4"><span className="text-sm font-bold">{option.label}</span>{selected?<span className="text-xs text-white/45">{pct}%</span>:null}</span></button>})}</div><div className="mt-3 flex items-center justify-between text-xs text-white/38"><span>{total.toLocaleString()} signals</span>{selected?<span className="font-bold text-[#ff9a4d]">Demand updated</span>:<span>Tap one</span>}</div></section>;
}

