function PromoKeyPage({ path }: { path: string }) {
  const [used,setUsed]=useState(false);
  return <Shell active="card" path={path}><SEO title="PromoKey — PROMORANG Review" description="Illustrative PromoKey detail."/><DeepHeader parent="card" kicker="PromoKey · Access" title="AFTRHRS Wing Key" copy="A PromoKey is compact gated access: a perk, entitlement or door that can expire and be redeemed."/><div className="px-5 py-7 sm:px-7 lg:px-8"><section className="rounded-[1.8rem] border border-[#d49a35]/30 bg-[radial-gradient(circle_at_100%_0%,rgba(246,196,83,.14),transparent_38%),#0d0d0e] p-6"><div className="flex items-start justify-between"><div><KeyRound className="h-7 w-7 text-[#f6c453]"/><p className="mt-5 text-[10px] font-black uppercase tracking-[.16em] text-[#ff9a4d]">PROMOKEY · PK-0218</p><h2 className="mt-2 font-serif text-3xl font-bold">Complimentary wings</h2><p className="mt-2 text-sm text-white/50">Sea Deck · AFTRHRS</p></div><span className={`rounded-full px-3 py-2 text-[10px] font-black ${used?"bg-white/10 text-white/45":"bg-green-400/10 text-green-300"}`}>{used?"USED":"ACTIVE"}</span></div><dl className="mt-7 grid grid-cols-2 gap-4 border-t border-white/10 pt-5 text-xs"><div><dt className="text-white/35">VALID</dt><dd className="mt-1 font-bold">Wed · 10 PM–12 AM</dd></div><div><dt className="text-white/35">VENUE</dt><dd className="mt-1 font-bold">Sea Deck</dd></div><div><dt className="text-white/35">USES</dt><dd className="mt-1 font-bold">{used?"0 remaining":"1 remaining"}</dd></div><div><dt className="text-white/35">ISSUER</dt><dd className="mt-1 font-bold">AFTRHRS</dd></div></dl><div className="mt-6"><ActionButton light onClick={()=>setUsed(true)}>{used?"View proof":"Use PromoKey"}</ActionButton></div></section>{used?<div className="mt-6"><PaperReceipt heading="KEY REDEEMED" lines={[{label:"Key",value:"PK-0218"},{label:"Perk",value:"Complimentary wings",strong:true},{label:"Place",value:"Sea Deck"},{label:"Proof",value:"Verified"}]} footer="Access returned as proof."/></div>:null}</div></Shell>;
}

function PromoSharePage({ path }: { path: string }) {
  const [tickets,setTickets]=useState(6);
  return <Shell active="vault" path={path}><SEO title="PromoShare — PROMORANG Review" description="Illustrative named perk draw."/><DeepHeader parent="vault" kicker="PromoShare · Perk draw" title="Kingston Food Drop" copy="PromoShare tickets are chances in a named draw whose prize is already stated. This example is a perk draw, not Save & Win."/><div className="px-5 py-7 sm:px-7 lg:px-8"><section className="rounded-[1.8rem] border border-[#d49a35]/30 bg-[radial-gradient(circle_at_100%_0%,rgba(246,196,83,.13),transparent_40%),#0d0d0e] p-6"><div className="flex items-center justify-between"><Ticket className="h-7 w-7 text-[#f6c453]"/><span className="rounded-full border border-white/10 px-3 py-2 text-[10px] font-black text-white/55">DRAW · PS-0920</span></div><p className="mt-6 text-[10px] font-black uppercase tracking-[.16em] text-[#ff9a4d]">Published prize</p><h2 className="mt-2 font-serif text-3xl font-bold">Dinner for two + Wing PromoKey</h2><p className="mt-3 text-sm text-white/50">Illustrative partner perk already set aside for this draw.</p><div className="mt-6 grid grid-cols-2 gap-3"><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] uppercase tracking-[.12em] text-white/35">Your tickets</p><p className="mt-2 text-3xl font-black text-[#f6c453]">{tickets}</p></div><div className="rounded-xl border border-white/10 p-4"><Clock3 className="h-4 w-4 text-[#ff9a4d]"/><p className="mt-2 text-sm font-black">Closes tonight · 8 PM</p></div></div><div className="mt-6"><ActionButton onClick={()=>setTickets(v=>v+1)}>Share for another ticket</ActionButton></div></section><section className="mt-6"><p className="text-[10px] font-black uppercase tracking-[.16em] text-white/38">How your tickets arrived</p><div className="mt-3 grid gap-3 sm:grid-cols-3">{[["2","Participation"],["3","Sharing"],["1","Partner action"]].map(([n,label])=><div key={label} className="rounded-xl border border-white/10 p-4"><p className="text-2xl font-black">{n}</p><p className="mt-1 text-xs text-white/42">{label}</p></div>)}</div></section><section className="mt-6 rounded-[1.5rem] border border-white/10 p-5"><MarkLabel kind="proof">Draw clarity</MarkLabel><p className="mt-3 text-sm leading-6 text-white/50">Tickets affect chances in this named random draw. They are not Gems, not withdrawable value and not the same thing as leaderboard points.</p></section></div></Shell>;
}

function SaveWinPage({ path }: { path: string }) {
  const [parked,setParked]=useState(25);
  const tickets=Math.floor(parked/5);
  return <Shell active="vault" path={path}><SEO title="Save & Win — PROMORANG Review" description="Illustrative Save & Win pot."/><DeepHeader parent="vault" kicker="PromoShare · Save & Win" title="Weekend 100 Gem Pot" copy="Save & Win is the money-draw family: park Gems, keep the principal, receive tickets for the named draw, and compete for an extra Gem prize already committed to the pot."/><div className="px-5 py-7 sm:px-7 lg:px-8"><section className="rounded-[1.8rem] border border-[#4cc6f0]/30 bg-[radial-gradient(circle_at_100%_0%,rgba(76,198,240,.12),transparent_40%),#0d0d0e] p-6"><div className="flex items-center justify-between"><Trophy className="h-7 w-7 text-[#4cc6f0]"/><span className="rounded-full border border-white/10 px-3 py-2 text-[10px] font-black text-white/55">POT · SW-0100</span></div><p className="mt-6 text-[10px] font-black uppercase tracking-[.16em] text-[#4cc6f0]">Named prize</p><h2 className="mt-2 font-serif text-3xl font-bold">100 extra Gems</h2><div className="mt-6 grid grid-cols-3 gap-3"><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] text-white/35">PARKED</p><p className="mt-2 text-2xl font-black text-[#4cc6f0]">{parked}</p><p className="text-[10px] text-white/35">Gems</p></div><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] text-white/35">TICKETS</p><p className="mt-2 text-2xl font-black text-[#f6c453]">{tickets}</p></div><div className="rounded-xl border border-white/10 p-4"><p className="text-[10px] text-white/35">PRINCIPAL</p><p className="mt-2 text-sm font-black text-green-300">Remains yours</p></div></div><div className="mt-6"><ActionButton onClick={()=>setParked(v=>v+5)}>Park 5 more Gems</ActionButton></div></section><section className="mt-6 grid gap-4 lg:grid-cols-2"><div className="rounded-[1.5rem] border border-white/10 p-5"><Gem className="h-5 w-5 text-[#4cc6f0]"/><h3 className="mt-4 font-serif text-xl font-bold">What is parked?</h3><p className="mt-2 text-sm leading-6 text-white/45">Your own Gems assigned to this pot for ticket eligibility. Review values are illustrative.</p></div><div className="rounded-[1.5rem] border border-white/10 p-5"><Ticket className="h-5 w-5 text-[#f6c453]"/><h3 className="mt-4 font-serif text-xl font-bold">What can be won?</h3><p className="mt-2 text-sm leading-6 text-white/45">The published extra-Gem prize. Losing the draw does not consume the parked principal.</p></div></section></div></Shell>;
}

export default function ParticipantCompleteReviewV1() {
  const location=useLocation();
  const path=location.pathname;
  const active=parentSurface(path);
  if(path==="/"||path==="") return <Navigate to="/today" replace/>;
  if(path==="/today") return <TodaySurface path={path}/>;
  if(path==="/discover") return <DiscoverSurface path={path}/>;
  if(path==="/card") return <CardSurface path={path}/>;
  if(path==="/vault") return <VaultSurface path={path}/>;
  if(path==="/you") return <YouSurface path={path}/>;
  if(path==="/discover/poll") return <DiscoveryPollPage path={path}/>;
  if(path==="/discover/piece") return <PieceDetailPage path={path}/>;
  if(path==="/discover/marketplace") return <MarketplacePage path={path}/>;
  if(path==="/card/promokey") return <PromoKeyPage path={path}/>;
  if(path==="/vault/promoshare") return <PromoSharePage path={path}/>;
  if(path==="/vault/save-win") return <SaveWinPage path={path}/>;
  return <Navigate to={`/${active}`} replace/>;
}
